// Select Approved To Send (Day 15 gate: FR-15 suppression, FR-16 approval).
// Input: Suppression_List rows (one empty item if the tab is empty). Master rows come from 'Read Master'.
const TEST_MODE = true;                         // true = EVERY email goes to TEST_INBOX only. Set false only for a real send.
const TEST_INBOX = 'REPLACE_WITH_YOUR_TEST_EMAIL';   // an inbox you own; set it in n8n, do not commit it
const MAX_PER_RUN = 5;
const MIN_SCORE = 80;
const EMAIL_RE = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+$/;
const clean = v => String(v == null ? '' : v).trim();

if (TEST_MODE && !EMAIL_RE.test(TEST_INBOX)) throw new Error('SET_TEST_INBOX: put an email address you own in TEST_INBOX at the top of this node.');

const supEmails = new Set(), supDomains = new Set();
for (const it of $input.all()) {
  const s = it.json || {};
  const e = clean(s.email).toLowerCase(), d = clean(s.domain).toLowerCase().replace(/^www\./, '');
  if (e) supEmails.add(e);
  if (d) supDomains.add(d);
}

const out = [], skipped = [];
let toSend = 0, toSuppress = 0;
for (const it of $('Read Master').all()) {
  const r = it.json || {};
  const id = clean(r.master_lead_id);
  if (!id) continue;
  const approval = clean(r.human_approval).toUpperCase();
  if (approval !== 'APPROVED') { skipped.push({ id, reason: 'NOT_APPROVED(' + (approval || 'BLANK') + ')' }); continue; }
  const status = clean(r.outreach_status).toUpperCase();
  if (status === 'SENT' || clean(r.sent_at)) { skipped.push({ id, reason: 'ALREADY_SENT' }); continue; }
  if (status !== 'DRAFTED') { skipped.push({ id, reason: 'NOT_DRAFTED(' + (status || 'BLANK') + ')' }); continue; }
  const email = clean(r.verified_email), subject = clean(r.outreach_subject), draft = clean(r.outreach_draft);
  if (!EMAIL_RE.test(email)) { skipped.push({ id, reason: 'INVALID_EMAIL' }); continue; }
  if (!subject || !draft) { skipped.push({ id, reason: 'NO_DRAFT' }); continue; }
  if (!/UNSUBSCRIBE/.test(draft)) { skipped.push({ id, reason: 'DRAFT_MISSING_UNSUBSCRIBE_FOOTER' }); continue; }
  if (!(Number(clean(r.lead_score)) >= MIN_SCORE)) { skipped.push({ id, reason: 'SCORE_BELOW_80' }); continue; }
  const domain = (email.split('@')[1] || '').toLowerCase();
  const nd = clean(r.normalized_domain).toLowerCase();
  if (supEmails.has(email.toLowerCase()) || supDomains.has(domain) || (nd && supDomains.has(nd))) {
    out.push({ json: { action: 'SUPPRESS', master_lead_id: id, verified_email: email, reason: 'EMAIL_OR_DOMAIN_ON_SUPPRESSION_LIST' } });
    toSuppress++; continue;
  }
  if (toSend >= MAX_PER_RUN) { skipped.push({ id, reason: 'RUN_CAP_' + MAX_PER_RUN }); continue; }
  out.push({ json: { action: 'SEND', master_lead_id: id, company_name: clean(r.company_name), verified_email: email,
    outreach_subject: subject, outreach_draft: draft, human_approval: approval, current_status: status,
    test_mode: TEST_MODE, test_inbox: TEST_INBOX } });
  toSend++;
}
out.push({ json: { action: 'REPORT', test_mode: TEST_MODE, to_send: toSend, to_suppress: toSuppress, skipped_count: skipped.length, skipped } });
return out;

// Build Message: final safety assertions, then the plain-text message the Gmail node sends.
// In TEST_MODE the recipient is always the test inbox, never the lead.
const hdr = s => String(s == null ? '' : s).replace(/[\r\n]+/g, ' ').trim();   // no header injection
return $input.all().map(it => {
  const l = it.json;
  if (String(l.human_approval || '').trim().toUpperCase() !== 'APPROVED') throw new Error('DISPATCH_HALTED: Lead ' + l.master_lead_id + ' lacks explicit human approval.');
  if (!/UNSUBSCRIBE/.test(String(l.outreach_draft || ''))) throw new Error('DISPATCH_HALTED: Lead ' + l.master_lead_id + ' draft has no UNSUBSCRIBE footer.');
  const test = l.test_mode === true;
  const to = test ? hdr(l.test_inbox) : hdr(l.verified_email);
  const subject = (test ? '[TEST] ' : '') + hdr(l.outreach_subject);
  const message = (test ? '[TEST MODE] This would have been sent to: ' + hdr(l.verified_email) + '\n\n' : '') + String(l.outreach_draft).replace(/\r\n/g, '\n');
  return { json: { master_lead_id: l.master_lead_id, to, original_to: hdr(l.verified_email), subject, message, test_mode: test, current_status: l.current_status } };
});

// Record Result: pair each Gmail response with its lead by position and shape the sheet update.
const istNow = () => new Date(Date.now() + 5.5 * 3600 * 1000).toISOString().slice(0, 19).replace('T', ' ') + ' IST';
const sent = $('Build Message').all().map(x => x.json);
const res = $input.all().map(x => x.json);
return sent.map((l, i) => {
  const r = res[i] || {};
  const ok = !r.error && !!r.id;
  const now = istNow();
  const err = String((r.error && (r.error.message || r.error)) || 'NO_RESPONSE_FROM_GMAIL').slice(0, 150);
  let status, sentAt = '', msgId = '', notes;
  if (l.test_mode) {
    status = l.current_status || 'DRAFTED';     // a test send never marks the lead as SENT
    if (ok) { msgId = r.id; notes = 'TEST_SENT to ' + l.to + ' (would go to ' + l.original_to + ') at ' + now; }
    else notes = 'TEST_SEND_FAILED: ' + err;
  } else if (ok) { status = 'SENT'; sentAt = now; msgId = r.id; notes = 'SENT to ' + l.to; }
  else { status = 'FAILED'; notes = 'SEND_FAILED: ' + err; }
  return { json: { master_lead_id: l.master_lead_id, outreach_status: status, sent_at: sentAt, gmail_message_id: msgId, send_notes: notes } };
});

// Mark Suppressed: the lead is on the suppression list. Dispatch is aborted and the row is marked.
return $input.all().map(it => ({ json: {
  master_lead_id: it.json.master_lead_id,
  outreach_status: 'SUPPRESSED',
  sent_at: '',
  gmail_message_id: '',
  send_notes: 'SUPPRESSED: ' + it.json.reason
} }));
